"""SQL generated by the composite-FK helper.

Pure string generation - no database. These assert the two properties a
reviewer cannot check by reading a migration that calls the helper: that the
default constraint name is derived from table and column, and that an
explicit name overrides it.

The override exists because the default name is derived from the column
alone, so a column needing *two* composite foreign keys - one for tenant
safety, one for a business invariant - collides on it. Discovered while
building a product on this helper; kept because the sharp edge belongs to
the helper, not to that product (ADR-017).
"""

from __future__ import annotations

import pytest

from workeasy360.platform.tenancy.migrations_helpers import add_tenant_fk


def _sql(operation) -> str:
    return " ".join(str(operation.sql).split())


def test_default_constraint_name_is_derived_from_table_and_column():
    sql = _sql(
        add_tenant_fk(
            table="widget",
            column="gadget_id",
            references_table="gadget",
        )
    )
    assert "fk_widget_gadget_id_tenant" in sql
    assert '"organization_id"' in sql


def test_an_explicit_constraint_name_overrides_the_default():
    """Two composite FKs on one column need two names."""
    sql = _sql(
        add_tenant_fk(
            table="widget",
            column="gadget_id",
            references_table="gadget",
            tenant_column="assembly_id",
            constraint_name="fk_widget_gadget_id_assembly",
        )
    )
    assert "fk_widget_gadget_id_assembly" in sql
    assert "fk_widget_gadget_id_tenant" not in sql
    assert '"assembly_id"' in sql


def test_an_unsupported_on_delete_is_refused():
    """A typo here silently changes deletion semantics for a tenant table."""
    with pytest.raises(ValueError, match="Unsupported ON DELETE"):
        add_tenant_fk(
            table="widget",
            column="gadget_id",
            references_table="gadget",
            on_delete="DROP EVERYTHING",
        )
